"""Empirical d-regularity, edge-count, and connectivity of the Boolean
hypercube flip graph Q_d, verifying the main reconfiguration theorems."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Cfg = Tuple[bool, ...]

def configs(d: int) -> List[Cfg]:
    return [tuple(b) for b in product([False, True], repeat=d)]

def hamming(a: Cfg, b: Cfg) -> int:
    return sum(1 for x, y in zip(a, b) if x != y)

def degree(a: Cfg, all_c: List[Cfg]) -> int:
    return sum(1 for b in all_c if hamming(a, b) == 1)

def edges(d: int) -> int:
    c = configs(d)
    return sum(1 for i, a in enumerate(c) for b in c[i+1:] if hamming(a, b) == 1)

def connected(d: int) -> bool:
    c = configs(d)
    # path = toggle disagreeing coordinates one at a time
    for a in c:
        for b in c:
            cur = a
            for i in range(d):
                if cur[i] != b[i]:
                    cur = tuple(not x if j == i else x for j, x in enumerate(cur))
            if cur != b:
                return False
    return True

def main() -> None:
    for d in range(1, 7):
        c = configs(d)
        degs = {degree(a, c) for a in c}
        # flipGraph_degree / flipGraph_degree_four:
        assert degs == {d}, f"Q_{d} not d-regular"
        # flipGraph_card_edges:
        assert 2 * edges(d) == d * 2 ** d
        print(f"Q_{d}: vertices={2**d:3d}  degree={d}  edges={edges(d):3d}"
              f"  connected={connected(d)}")
    print("d-regularity, edge count (d*2^(d-1)) and connectivity: verified.")

if __name__ == "__main__":
    main()

