function NEIGHBOURS(a):              # a in {0,1}^d
    nbrs <- []
    for i in 0 .. d-1:
        b <- copy(a); b[i] <- not b[i]
        nbrs.append(b)
    return nbrs                      # |nbrs| = d  (flipGraph_degree)

function DEGREE(a):
    return length(NEIGHBOURS(a))

