function SHORTEST_FLIP_PATH(a, b):    # a, b in {0,1}^d
    path <- [a]; cur <- a
    for i in 0 .. d-1:
        if cur[i] != b[i]:
            cur <- toggle(cur, i)     # single legal flip
            path.append(cur)
    assert last(path) == b            # flipGraph_connected
    return path                       # length = HammingDistance(a, b)

